const GLOSSARY = [
    { term: 'Schema', def: 'The fixed map of tables, columns and types a relational engine enforces on every row.' },
    { term: 'ACID', def: 'Atomicity, Consistency, Isolation, Durability — a transaction fully happens or not at all, even under crash and concurrency.' },
    { term: 'BASE', def: 'Basically Available, Soft state, Eventually consistent — the availability-first trade most NoSQL stores make.' },
    { term: 'CAP theorem', def: 'Under a network partition a distributed store must choose consistency or availability — not both.' },
    { term: 'Eventual consistency', def: 'Replicas converge over time; a read right after a write may not see it.' },
    { term: 'Replication lag', def: 'The delay before a committed write becomes visible on asynchronous replicas.' },
    { term: 'Read replica', def: 'Asynchronous copy serving read traffic; scales reads, offloads reporting, can be promoted.' },
    { term: 'Synchronous standby (multi-AZ)', def: 'Hot in-step copy in another zone with automatic failover — resilience, not read scaling; costs write latency.' },
    { term: 'Multi-primary (active-active)', def: 'Writes accepted in more than one place — write availability and locality, at the cost of write conflicts.' },
    { term: 'Sharding / shard key', def: 'Horizontally partitioning rows across nodes; the key decides distribution, cardinality and hot-spot risk.' },
    { term: 'DBaaS', def: 'Managed database service: provider owns patching, backups, replication, failover; you keep schema, data, access and cost.' },
    { term: 'Point-in-time recovery (PITR)', def: 'Restore to any moment inside the retention window by replaying transaction logs onto a base backup.' },
    { term: 'Retention window', def: 'The finite period (days to weeks) automated backups stay recoverable.' },
    { term: 'OLTP vs OLAP', def: 'Transactional single-row operations vs analytical aggregation over huge volumes — the latter is warehouse territory.' },
    { term: 'Cache invalidation', def: 'Removing stale cached entries when the source changes; TTL is simple but serves stale data.' },
];
