// ---------- Resilience (R-600) ----------
const RPO_RTO = {
    compute: (r) => {
        let rpo = 24 * 60; // daily backup only
        if (r.autoBackups)
            rpo = 12 * 60;
        if (r.pitr)
            rpo = 5;
        let rto = 8 * 60;
        if (r.multiAz)
            rto = 2;
        if (!r.autoBackups && !r.pitr)
            rto = 12 * 60;
        const survivesInstanceDelete = r.snapshotSchedule;
        const survivesRegion = r.crossRegion;
        const survivesAccount = r.crossAccount;
        return { rpo, rto, survivesInstanceDelete, survivesRegion, survivesAccount };
    },
    cost: (r) => {
        let c = 240; // base instance
        if (r.pitr)
            c += 120;
        if (r.retentionDays === 14)
            c += 60;
        if (r.retentionDays === 35)
            c += 140;
        if (r.snapshotSchedule)
            c += 90;
        if (r.crossRegion)
            c += 310;
        if (r.crossAccount)
            c += 150;
        if (r.offlineVault)
            c += 3500;
        if (r.multiAz)
            c += 240;
        return c;
    },
};
